-- Portfolio snapshot: 20 November 2026. Literal fictional fixtures, no provider calls.
CREATE TEMP TABLE story_people(id uuid PRIMARY KEY,side text,first_name text,last_name text,city text,langs text[],food text,character text,approved boolean,manual boolean);
-- Rebuild quick-login staff without a persons row.
VALUES('2f79a37c-468f-4bf5-90c4-c0adef2190cc','00000000-0000-0000-0000-000000000000','authenticated','authenticated','staff@demo.shabbat-babayit.example',now(),'{"provider":"email","providers":["email"]}','{}',now(),now()) ON CONFLICT(id) DO NOTHING;
SELECT id,'00000000-0000-0000-0000-000000000000','authenticated','authenticated',CASE id WHEN '809f85d8-4640-4860-badc-45cba7b5fb4a' THEN 'guest@demo.shabbat-babayit.example' WHEN 'ed5895e3-934e-4220-91a1-f70cc937103c' THEN 'host@demo.shabbat-babayit.example' ELSE side||'-'||right(id::text,3)||'@demo.shabbat-babayit.example' END,now(),'{"provider":"email","providers":["email"]}','{}','2026-10-01',now() FROM story_people ON CONFLICT(id) DO NOTHING;
DO $details$ DECLARE p record; serial integer:=100; ident text; BEGIN FOR p IN SELECT * FROM story_people ORDER BY id LOOP
serial:=serial+1; SELECT lpad(serial::text,8,'0')||d::text INTO ident FROM generate_series(0,9) d WHERE public.is_valid_il_id(lpad(serial::text,8,'0')||d::text) LIMIT 1;
UPDATE public.persons SET first_name=p.first_name,last_name=p.last_name,phone='0500000'||serial::text,phone_verified_at='2026-10-01',id_number=CASE WHEN id IN('809f85d8-4640-4860-badc-45cba7b5fb4a','ed5895e3-934e-4220-91a1-f70cc937103c') THEN id_number ELSE ident END,date_of_birth='1990-01-01',notification_channel=CASE WHEN p.side='host' THEN 'voice'::public.notification_channel ELSE 'sms'::public.notification_channel END,onboarding_step=CASE WHEN p.manual THEN 'identity' ELSE 'role' END WHERE id=p.id;
END LOOP; END $details$;
SELECT id,last_name,'רחל','000000034','רחוב הדגמה','1','שכונת הדגמה',city,'זוג ושלושה ילדים',39,36,ARRAY[5,9,12],langs,ARRAY['מוזיקה','היסטוריה','טבע וטיולים'],food,character,'משפחה בדיונית בסיפור ההדגמה. נשמח לשיחה ולשבת נעימה.','אין גישה לכיסא גלגלים','staff_call','video',true,true,true,true,'2026-10-01','2026-10-01',CASE WHEN manual THEN 'partial'::public.profile_status WHEN approved THEN 'active'::public.profile_status ELSE 'pending'::public.profile_status END,CASE WHEN approved THEN 'approved'::public.host_approval ELSE 'pending'::public.host_approval END,CASE WHEN approved THEN '2026-10-15'::timestamptz END,CASE WHEN manual THEN 0 ELSE 10 END,6,6 FROM story_people WHERE side='host'
ON CONFLICT(person_id) DO UPDATE SET family_name=EXCLUDED.family_name,city=EXCLUDED.city,languages=EXCLUDED.languages,interests=EXCLUDED.interests,food_offer=EXCLUDED.food_offer,house_character=EXCLUDED.house_character,about=EXCLUDED.about,default_seats=6,default_beds=6;
UPDATE public.host_profiles SET recommendation_mode='recommenders',staff_call_method=NULL,recommender_name='ממליץ בדיוני ראשון',recommender_phone='0500000901',recommender2_name='ממליץ בדיוני שני',recommender2_phone='0500000902',recommender_role='נציג קהילה לדוגמה' WHERE person_id IN('a4000000-0000-4000-8000-000000000001','a4000000-0000-4000-8000-000000000002','a4000000-0000-4000-8000-000000000008');
SELECT id,CASE WHEN first_name IN('נועה','מיכל','תמר','שרה','יעל') THEN 'female'::public.gender ELSE 'male'::public.gender END,'רווק/ה',langs,'little',city,true,ARRAY['מוזיקה','היסטוריה','טבע וטיולים'],food,CASE WHEN first_name='תמר' THEN 'ללא גלוטן' END,character,'2026-10-01','active',7,CASE WHEN first_name='תמר' THEN 2 ELSE 0 END,'full_shabbat',true,'2026-11-15' FROM story_people WHERE side='guest'
ON CONFLICT(person_id) DO UPDATE SET city=EXCLUDED.city,languages=EXCLUDED.languages,interests=EXCLUDED.interests,food_preferences=EXCLUDED.food_preferences,about=EXCLUDED.about,weekly_prompt_week=EXCLUDED.weekly_prompt_week;
-- Give both sides sufficient verified levels, but preserve the manual-review case.
UPDATE public.persons SET onboarding_step='done' WHERE id IN(SELECT id FROM story_people WHERE NOT manual);
SELECT s.id,s.side::public.app_role,k::public.verification_kind,'passed','mock_story','2026-10-15' FROM story_people s CROSS JOIN (VALUES('id'),('intro_call')) kinds(k) WHERE NOT s.manual AND NOT EXISTS(SELECT 1 FROM public.verifications v WHERE v.person_id=s.id AND v.profile_role=s.side::public.app_role AND v.kind=k::public.verification_kind AND v.status='passed');
-- Six coming Shabbatot, mixed meals/lodging. Full Shabbat always includes lodging under existing rules.
SELECT ('a4100000-0000-4000-8000-'||lpad((h.n*10+d.n)::text,12,'0'))::uuid,h.id,d.date,CASE WHEN h.n%4=0 THEN 'full_shabbat'::public.hosting_unit WHEN h.n%4=1 THEN 'friday_dinner'::public.hosting_unit WHEN h.n%4=2 THEN 'shabbat_lunch'::public.hosting_unit ELSE 'seudah_shlishit'::public.hosting_unit END,h.n%2=0,6,6,CASE WHEN h.n%2=0 THEN 6 ELSE 0 END,'הזמנה פיקטיבית לסיפור ההדגמה'
FROM (VALUES(0,'ed5895e3-934e-4220-91a1-f70cc937103c'::uuid),(1,'a4000000-0000-4000-8000-000000000001'::uuid),(2,'a4000000-0000-4000-8000-000000000002'::uuid),(3,'a4000000-0000-4000-8000-000000000003'::uuid),(4,'a4000000-0000-4000-8000-000000000004'::uuid),(5,'a4000000-0000-4000-8000-000000000005'::uuid),(6,'a4000000-0000-4000-8000-000000000006'::uuid),(7,'a4000000-0000-4000-8000-000000000007'::uuid)) h(n,id)
CROSS JOIN (VALUES(1,'2026-11-21'::date),(2,'2026-11-28'::date),(3,'2026-12-05'::date),(4,'2026-12-12'::date),(5,'2026-12-19'::date),(6,'2026-12-26'::date)) d(n,date) ON CONFLICT DO NOTHING;
CREATE TEMP TABLE story_visits(n integer PRIMARY KEY,guest uuid,host uuid,date date,status public.hosting_status,overall text,partial boolean);
SELECT ('a4200000-0000-4000-8000-'||lpad(v.n::text,12,'0'))::uuid,host,date,'full_shabbat',true,6,6,6,'אירוח פיקטיבי בסיפור ההדגמה' FROM story_visits v JOIN public.guest_profiles g ON g.person_id=v.guest ON CONFLICT DO NOTHING;
ALTER TABLE story_visits ADD COLUMN slot uuid;
UPDATE story_visits v SET slot=(SELECT id FROM public.availability WHERE host_id=v.host AND shabbat_date=v.date AND unit='full_shabbat');
SELECT ('a4300000-0000-4000-8000-'||lpad(v.n::text,12,'0'))::uuid,guest,date,g.party_type,g.party_adults,array_fill(0,ARRAY[g.minor_children_count]),'full_shabbat',true,CASE WHEN v.status='cancelled_host' THEN 'active'::public.request_status ELSE 'closed'::public.request_status END FROM story_visits v JOIN public.guest_profiles g ON g.person_id=v.guest ON CONFLICT(id) DO NOTHING;
SELECT ('a4400000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('a4300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,slot,guest,host,'accepted',(date-7)::timestamptz,(date-6)::timestamptz,'נשמח להכיר את המשפחה ולשוחח סביב שולחן השבת.' FROM story_visits ON CONFLICT(id) DO NOTHING;
SELECT ('a4500000-0000-4000-8000-'||lpad(v.n::text,12,'0'))::uuid,('a4400000-0000-4000-8000-'||lpad(v.n::text,12,'0'))::uuid,slot,guest,host,date,g.party_adults+g.minor_children_count,v.status,CASE WHEN v.n%2=0 THEN 'phone_call'::public.contact_method ELSE 'whatsapp'::public.contact_method END,NULL,NULL,CASE WHEN v.status='cancelled_host' THEN host END,CASE WHEN v.status='cancelled_host' THEN 'illness' END,CASE WHEN v.status='cancelled_host' THEN 'מחלה פתאומית – ביטול חריג פיקטיבי לצורך הדגמה' END,CASE WHEN v.status='cancelled_host' THEN '2026-11-20T08:00:00Z'::timestamptz END,v.status='cancelled_host',v.status='cancelled_host',v.status='cancelled_host',CASE WHEN v.status='cancelled_host' THEN 'exceptional_cancellation' END FROM story_visits v JOIN public.guest_profiles g ON g.person_id=v.guest ON CONFLICT(id) DO NOTHING;
UPDATE public.availability a SET seats_left=a.seats-(SELECT COALESCE(sum(h.party_size),0) FROM public.hostings h WHERE h.availability_id=a.id AND h.status IN('confirmed','under_review','took_place','did_not_take_place')) WHERE a.id IN(SELECT slot FROM story_visits);
SELECT ('a4500000-0000-4000-8000-'||lpad(v.n::text,12,'0'))::uuid,p.uid,p.side::public.app_role,CASE WHEN v.partial THEN 'partial'::public.took_place ELSE 'yes'::public.took_place END,jsonb_build_object('overall',CASE WHEN p.side='guest' THEN v.overall ELSE 'מעולה' END),CASE WHEN v.partial THEN 'יציאה מוקדמת עקב אי הבנה. תרחיש פיקטיבי לבירור צוות.' WHEN v.overall='לא טוב' THEN 'פער בציפיות. תרחיש פיקטיבי למעקב צוות.' END FROM story_visits v CROSS JOIN LATERAL (VALUES(v.guest,'guest'),(v.host,'host')) p(uid,side) WHERE v.overall IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.feedback f WHERE f.hosting_id=('a4500000-0000-4000-8000-'||lpad(v.n::text,12,'0'))::uuid AND f.author_id=p.uid);
SELECT guest,'feedback_attention',host,'hostings',('a4500000-0000-4000-8000-'||lpad(n::text,12,'0')),'תרחיש פיקטיבי למעקב משוב',jsonb_build_object('partial',partial,'strong',false) FROM story_visits WHERE overall='לא טוב' OR partial;
-- Three still-pending responses, including one for quick-login host.
