SELECT ('a4600000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,g.person_id,'2026-12-12',g.party_type,g.party_adults,array_fill(0,ARRAY[g.minor_children_count]),'full_shabbat',true,'active' FROM (VALUES(1,'a4000000-0000-4000-8000-000000000015'::uuid),(2,'a4000000-0000-4000-8000-000000000014'::uuid),(3,'a4000000-0000-4000-8000-000000000012'::uuid)) v(n,id) JOIN public.guest_profiles g ON g.person_id=v.id ON CONFLICT(id) DO NOTHING;
