('a4700000-0000-4000-8000-000000000003','a4600000-0000-4000-8000-000000000003','a4100000-0000-4000-8000-000000000044','a4000000-0000-4000-8000-000000000012','a4000000-0000-4000-8000-000000000004','pending','אשמח לשבת עם שיחה ומוזיקה.',now()+interval '24 hours') ON CONFLICT(id) DO NOTHING;
